const stageSetup = "$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\n$image=$null;$partition=$null;$disk=$null;$phaseCode=10;$aclError=0\nfunction Assert-EmptyAnswerDirectory([string]$Path) {\n if(!(Test-Path -LiteralPath $Path)){return}\n $item=Get-Item -LiteralPath $Path -Force\n if(!$item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or @(Get-ChildItem -LiteralPath $Path -Force | Select-Object -First 1).Count){throw 'Embedded answer directory must be empty and ordinary'}\n}\ntry {\n $principal=[Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())\n if(!$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){exit $phaseCode}\n $data=[Console]::In.ReadToEnd() | ConvertFrom-Json\n if($data.instance_id -cnotmatch '^[0-9a-f]{32}$'){exit $phaseCode}\n $child=Join-Path $data.root $data.instance_id\n $expectedDisk=Join-Path $child 'disk.vhdx'\n if($data.disk -cne $expectedDisk -or ((Get-Item -LiteralPath $child).Attributes -band [IO.FileAttributes]::ReparsePoint) -or ((Get-Item -LiteralPath $expectedDisk).Attributes -band [IO.FileAttributes]::ReparsePoint)){exit $phaseCode}\n $marker=Get-Content -LiteralPath (Join-Path $child 'owner.json') -Raw | ConvertFrom-Json\n if($marker.build_id -cne $data.instance_id -or $marker.workspace -cne $child){exit $phaseCode}\n if((Get-DiskImage -ImagePath $expectedDisk).Attached){exit $phaseCode}\n $phaseCode=20\n $null=Add-Type -TypeDefinition @\"\nusing System;using System.Runtime.InteropServices;\npublic static class SpikeOfflineAnswer {\n [DllImport(\"offreg.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint OROpenHive(string path,out IntPtr hive);\n [DllImport(\"offreg.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint ORCloseHive(IntPtr hive);\n [DllImport(\"offreg.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint ORGetValue(IntPtr hive,string key,string value,out uint type,byte[] data,ref uint size);\n [DllImport(\"advapi32.dll\",CharSet=CharSet.Unicode,SetLastError=true),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern bool ConvertStringSecurityDescriptorToSecurityDescriptor(string text,uint revision,out IntPtr descriptor,out uint size);\n [DllImport(\"advapi32.dll\",SetLastError=true),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern bool GetSecurityDescriptorDacl(IntPtr descriptor,out bool present,out IntPtr dacl,out bool defaulted);\n [DllImport(\"advapi32.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint SetNamedSecurityInfo(string path,int kind,uint info,IntPtr owner,IntPtr group,IntPtr dacl,IntPtr sacl);\n [DllImport(\"kernel32.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern IntPtr LocalFree(IntPtr memory);\n public static uint ProtectDirectory(string path,string text) {\n  IntPtr descriptor;uint size;if(!ConvertStringSecurityDescriptorToSecurityDescriptor(text,1,out descriptor,out size))return (uint)Marshal.GetLastWin32Error();\n  try{bool present,defaulted;IntPtr dacl;if(!GetSecurityDescriptorDacl(descriptor,out present,out dacl,out defaulted))return (uint)Marshal.GetLastWin32Error();if(!present || dacl==IntPtr.Zero)return 87;return SetNamedSecurityInfo(path,1,0x80000004,IntPtr.Zero,IntPtr.Zero,dacl,IntPtr.Zero);}finally{LocalFree(descriptor);}\n }\n public static bool NoExplicitAnswer(string path) {\n  IntPtr hive;uint error=OROpenHive(path,out hive);if(error!=0)return false;\n  try{uint type=0,size=0;error=ORGetValue(hive,\"Setup\",\"UnattendFile\",out type,null,ref size);if(error==2)return true;if(error!=0 || type!=1 || size>2)return false;byte[] data=new byte[size];error=ORGetValue(hive,\"Setup\",\"UnattendFile\",out type,data,ref size);return error==0 && Array.TrueForAll(data,b=>b==0);}finally{ORCloseHive(hive);}\n }\n}\n\"@\n $mount=Join-Path $child 'setup-private\\mount'\n if(Test-Path -LiteralPath $mount){exit $phaseCode}\n New-Item -ItemType Directory -Path $mount | Out-Null\n $access=$mount+'\\'\n try {\n  $phaseCode=30\n  $image=Mount-DiskImage -ImagePath $expectedDisk -Access ReadWrite -NoDriveLetter -PassThru\n  $disk=$image | Get-Disk\n  if($disk.IsReadOnly -or $disk.IsOffline){throw 'Owned child is not online read-write'}\n  $partition=Get-Partition -DiskNumber $disk.Number | Sort-Object Size -Descending | Select-Object -First 1\n  $null=Add-PartitionAccessPath -DiskNumber $disk.Number -PartitionNumber $partition.PartitionNumber -AccessPath $access\n  $phaseCode=40\n  foreach($relative in @('Windows','Windows\\Panther','Windows\\System32','Windows\\System32\\config','Windows\\System32\\config\\SYSTEM')){\n   $path=Join-Path $mount $relative\n   if(!(Test-Path -LiteralPath $path) -or ((Get-Item -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Expected child Windows path unavailable'}\n  }\n  $phaseCode=50\n  $system=Join-Path $mount 'Windows\\System32\\config\\SYSTEM'\n  if((Get-Item -LiteralPath $system).Length -gt 256MB -or ![SpikeOfflineAnswer]::NoExplicitAnswer($system)){throw 'Offline explicit answer pointer must be absent'}\n  # The embedded answer directory outranks the template's cached Audit-mode\n  # file. Only an absent or empty directory is accepted; the parent stays pinned.\n  $phaseCode=60\n  $answerDirectory=Join-Path $mount 'Windows\\Panther\\Unattend'\n  Assert-EmptyAnswerDirectory $answerDirectory\n  $phaseCode=61\n  if(!(Test-Path -LiteralPath $answerDirectory)){New-Item -ItemType Directory -Path $answerDirectory | Out-Null}\n  $phaseCode=62\n  # Apply only the protected DACL; PowerShell Set-Acl can also touch audit/owner\n  # sections inherited from the guest image, which are outside this operation.\n  $aclError=[SpikeOfflineAnswer]::ProtectDirectory($answerDirectory,'D:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)')\n  if($aclError -ne 0){throw 'Cannot protect child answer directory'}\n  $phaseCode=63\n  foreach($entry in @(@('specialize.ps1',$data.specialize),@('unattend.xml',$data.unattend))){\n   $file=Join-Path $answerDirectory $entry[0]\n   $content=[Text.Encoding]::UTF8.GetBytes($entry[1])\n   $output=[IO.File]::Open($file,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)\n   try{$output.Write($content,0,$content.Length);$output.Flush($true)}finally{$output.Dispose();[Array]::Clear($content,0,$content.Length)}\n  }\n  $phaseCode=64\n  Install-OfflineAgent $mount $data.agent $data.agent_sha256\n  $phaseCode=65\n  Copy-OfflineDrivers $mount (Join-Path $child 'drivers') ($data.driver_plan | ConvertFrom-Json)\n } finally {\n  if($image){try{if($partition){$null=Remove-PartitionAccessPath -DiskNumber $disk.Number -PartitionNumber $partition.PartitionNumber -AccessPath $access}}finally{$null=Dismount-DiskImage -ImagePath $expectedDisk}}\n }\n $phaseCode=70\n if((Get-DiskImage -ImagePath $expectedDisk).Attached){exit $phaseCode}\n exit 0\n} catch {\n if($phaseCode -eq 62 -and $aclError -gt 0 -and $aclError -le 65535){exit (10000+[int]$aclError)}\n # Offline payload failures report the failing line of this fixed script\n # (offline payload followed by staging), never error text: phase*100000+line.\n $line=$_.InvocationInfo.ScriptLineNumber\n if($phaseCode -in @(64,65) -and $line -gt 0 -and $line -lt 100000){exit ($phaseCode*100000+[int]$line)}\n exit $phaseCode\n}\n"

const guestSpecialize = "$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\n$step=80\n$videoDiagnostics=@{}\nfunction Write-SetupStep([int]$Code,[bool]$Failed){\n [IO.File]::WriteAllText('C:\\Windows\\Panther\\Unattend\\setup-step.json',(@{step=$Code;failed=$Failed;video=$videoDiagnostics}|ConvertTo-Json -Compress -Depth 8),[Text.UTF8Encoding]::new($false))\n}\ntry {\n Write-SetupStep $step $false\n if(Get-Service AppSandboxAgent -ErrorAction SilentlyContinue){Set-Service AppSandboxAgent -StartupType Disabled}\n function Remove-BoundedTree([string]$Path){\n  if(!(Test-Path -LiteralPath $Path)){return}\n  $current=$Path\n  while($current){if((Get-Item -Force -LiteralPath $current).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'removal path link'};$current=Split-Path -Parent $current}\n  $queue=[Collections.Generic.Queue[string]]::new();$queue.Enqueue($Path);$count=0\n  while($queue.Count){foreach($entry in @(Get-ChildItem -LiteralPath ($queue.Dequeue()) -Force)){\n   $count++;if($count -gt 16384 -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'removal bound or link'}\n   if($entry.PSIsContainer){$queue.Enqueue($entry.FullName)}\n  }}\n  Remove-Item -LiteralPath $Path -Recurse -Force\n }\n function Remove-FixedService([string]$Name){\n  $service=Get-Service -Name $Name -ErrorAction SilentlyContinue\n  if(!$service){return}\n  if($service.Status -ne 'Stopped'){Stop-Service -Name $Name -Force;$service.WaitForStatus([System.ServiceProcess.ServiceControllerStatus]::Stopped,[TimeSpan]::FromSeconds(30))}\n  & (Join-Path $env:SystemRoot 'System32\\sc.exe') @('delete',$Name) *> $null\n  if($LASTEXITCODE){throw 'service deletion'}\n }\n New-ItemProperty -Path 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\OOBE' -Name BypassNRO -Value 1 -PropertyType DWord -Force | Out-Null\n\n $step=81;Write-SetupStep $step $false\n Remove-FixedService 'AppSandboxAgent'\n function Get-VDDNodes {\n  # No PresentOnly: phantom root nodes must be removed too.\n  $nodes=@(Get-PnpDevice | Where-Object InstanceId -like 'ROOT\\APPSANDBOXVDD\\*')\n  if($nodes.Count -gt 256){throw 'device bound'}\n  return $nodes\n }\n function Get-VDDPackages {\n  $packages=@(Get-WindowsDriver -Online -All | Where-Object { [IO.Path]::GetFileName($_.OriginalFileName) -ieq 'AppSandboxVDD.inf' })\n  if($packages.Count -gt 256){throw 'package bound'}\n  return $packages\n }\n $pnp=Join-Path $env:SystemRoot 'System32\\pnputil.exe'\n $step=82;Write-SetupStep $step $false\n foreach($node in @(Get-VDDNodes)){\n  $ids=@((Get-PnpDeviceProperty -InstanceId $node.InstanceId -KeyName 'DEVPKEY_Device_HardwareIds').Data)\n  if('ROOT\\APPSANDBOXVDD' -notin $ids){throw 'device identity'}\n  & $pnp @('/remove-device',$node.InstanceId) *> $null\n  if($LASTEXITCODE -notin @(0,3010)){throw 'device removal'}\n }\n $step=83;Write-SetupStep $step $false\n foreach($package in @(Get-VDDPackages)){\n  if($package.Driver -notmatch '^oem[0-9]+\\.inf$'){throw 'package identity'}\n  & $pnp @('/delete-driver',$package.Driver,'/uninstall','/force') *> $null\n  if($LASTEXITCODE -notin @(0,3010)){throw 'package removal'}\n }\n $step=84;Write-SetupStep $step $false\n Remove-BoundedTree (Join-Path $env:SystemRoot 'AppSandbox')\n $step=85;Write-SetupStep $step $false\n $videoDiagnostics.specialize_before=Get-VideoSnapshot\n Write-SetupStep $step $false\n if(!$videoDiagnostics.specialize_before.node_count){throw 'synthetic video absent'}\n try{Enable-VideoNodes $videoDiagnostics.specialize_before $false}finally{\n  $videoDiagnostics.specialize_enable=$script:videoEnableResult\n  $videoDiagnostics.specialize_after=Get-VideoSnapshot\n  Write-SetupStep $step $false\n }\n if(!$videoDiagnostics.specialize_enable.returned){throw 'synthetic video enable failed'}\n # Windows setup's following boot settles PnP changes; do not reboot here.\n $step=90;Write-SetupStep $step $false\n $uninstalls=@('HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall','HKLM:\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall')\n $products=0\n foreach($registry in $uninstalls){\n  if(!(Test-Path -LiteralPath $registry)){continue}\n  $keys=@(Get-ChildItem -LiteralPath $registry);if($keys.Count -gt 4096){throw 'uninstall registry bound'}\n  foreach($key in $keys){\n   $product=Get-ItemProperty -LiteralPath $key.PSPath\n   if($product.DisplayName -notmatch '^OpenSSH(?:\\s|$)'){continue}\n   if($key.PSChildName -notmatch '^\\{[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\\}$'){throw 'uninstall product code'}\n   $products++;if($products -gt 8){throw 'uninstall product bound'}\n   $process=Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\\msiexec.exe') -ArgumentList @('/x',$key.PSChildName,'/qn','/norestart') -WindowStyle Hidden -Wait -PassThru\n   if($process.ExitCode -notin @(0,1605,3010)){throw 'uninstall failed'}\n  }\n }\n $step=86;Write-SetupStep $step $false\n # MSI uninstall owns its services first; remove only leftover server state.\n Remove-FixedService 'sshd'\n $step=91;Write-SetupStep $step $false\n foreach($path in @('C:\\Program Files\\OpenSSH','C:\\Program Files\\OpenSSH-Win64')){Remove-BoundedTree $path}\n $step=92;Write-SetupStep $step $false\n Remove-BoundedTree 'C:\\ProgramData\\ssh'\n $step=93;Write-SetupStep $step $false\n $profiles=@(Get-ChildItem -Directory -Force -LiteralPath 'C:\\Users');if($profiles.Count -gt 256){throw 'profile bound'}\n foreach($profile in $profiles){\n  foreach($name in @('authorized_keys','administrators_authorized_keys')){\n   $path=Join-Path $profile.FullName ('.ssh\\'+$name)\n   if(Test-Path -LiteralPath $path){Remove-BoundedTree $path}\n  }\n }\n $step=94;Write-SetupStep $step $false\n $oldTask=Get-ScheduledTask -TaskName 'bivouac-hcs-ssh-hostkeys' -ErrorAction SilentlyContinue\n if($oldTask){Unregister-ScheduledTask -TaskName 'bivouac-hcs-ssh-hostkeys' -Confirm:$false}\n $step=88;Write-SetupStep $step $false\n\n} catch {\n try{Write-SetupStep $step $true}catch{};exit $step\n}\n"

const guestValidate = "param($data)\n$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\n$rotated=$false\n$step=17\ntry {\n if($env:COMPUTERNAME -ine $data.name -or $env:USERNAME -ine $data.user) {exit 11}\n $step=19\n Add-Type -TypeDefinition @\"\nusing System;using System.Runtime.InteropServices;\npublic static class SpikeConsole {\n [DllImport(\"kernel32.dll\")] public static extern uint WTSGetActiveConsoleSessionId();\n [DllImport(\"wtsapi32.dll\",CharSet=CharSet.Unicode)] public static extern bool WTSQuerySessionInformation(IntPtr server,uint session,int info,out IntPtr buffer,out int bytes);\n [DllImport(\"wtsapi32.dll\")] public static extern void WTSFreeMemory(IntPtr buffer);\n}\n\"@\n $step=20\n $consoleBudget=[Diagnostics.Stopwatch]::StartNew()\n $stable=0\n while($consoleBudget.Elapsed.TotalSeconds -lt 180) {\n  $session=[SpikeConsole]::WTSGetActiveConsoleSessionId()\n  $matched=$false;$buffer=[IntPtr]::Zero;$size=0\n  if($session -ne 0 -and $session -ne [uint32]::MaxValue) {\n   try {if([SpikeConsole]::WTSQuerySessionInformation([IntPtr]::Zero,$session,5,[ref]$buffer,[ref]$size)) {$matched=([Runtime.InteropServices.Marshal]::PtrToStringUni($buffer) -ieq $data.user)}}finally{if($buffer -ne [IntPtr]::Zero){[SpikeConsole]::WTSFreeMemory($buffer)}}\n  }\n  $setup=Get-ItemProperty 'HKLM:\\SYSTEM\\Setup'\n  $explorer=@(Get-Process explorer -ErrorAction SilentlyContinue | Where-Object SessionId -eq $session)\n  if((!$data.require_setup -or (Test-Path -LiteralPath (Join-Path 'C:\\ProgramData\\Bivouac\\Image' 'hcs-spike-setup-complete.json'))) -and $matched -and $setup.SystemSetupInProgress -eq 0 -and $setup.OOBEInProgress -eq 0 -and $explorer.Count){$stable++}else{$stable=0}\n  if($stable -ge 5){break}\n  Start-Sleep -Milliseconds 500\n }\n if($stable -lt 5){exit 12}\n $base='C:\\ProgramData\\Bivouac\\Image\\Probe'\n if(Test-Path -LiteralPath $base){exit 13}\n $step=21\n New-Item -ItemType Directory -Path $base | Out-Null\n $acl=New-Object Security.AccessControl.DirectorySecurity\n $acl.SetSecurityDescriptorSddlForm('D:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)')\n Set-Acl -LiteralPath $base -AclObject $acl\n if($data.prepared -eq $true){\n  $marker=Join-Path 'C:\\ProgramData\\Bivouac\\Image' 'hcs-spike-prepared.json'\n  if(!(Test-Path -LiteralPath $marker -PathType Leaf) -or ((Get-Item -LiteralPath $marker).Attributes -band [IO.FileAttributes]::ReparsePoint) -or (Get-Item -LiteralPath $marker).Length -gt 4096){exit 21}\n  $image=Get-Content -LiteralPath $marker -Raw|ConvertFrom-Json\n  if($image.name -ine $data.name -or $image.user -ine $data.user -or $image.probe_sha256 -ine $data.sha256 -or $image.validation_sha256 -ine $data.script_sha256 -or $image.autologon_sha256 -ine $data.autologon_sha256){exit 21}\n  $secretHelper=Join-Path 'C:\\ProgramData\\Bivouac\\Image' 'hcs-spike-autologon.ps1'\n  if((Get-FileHash -LiteralPath $secretHelper -Algorithm SHA256).Hash -ine $data.autologon_sha256){throw 'Autologon helper integrity differs'}\n  . $secretHelper\n  $random=New-Object byte[] 32\n  $rng=[Security.Cryptography.RandomNumberGenerator]::Create()\n  try{$rng.GetBytes($random)}finally{$rng.Dispose()}\n  $password='Bv!'+[Convert]::ToBase64String($random)\n  $secure=[Security.SecureString]::new()\n  $characters=$password.ToCharArray()\n  try{foreach($character in $characters){$secure.AppendChar($character)};$secure.MakeReadOnly()}finally{[Array]::Clear($characters,0,$characters.Length)}\n  try{Set-LocalUser -Name $data.user -Password $secure}finally{$secure.Dispose()}\n  $logon=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon',$true)\n  try{if([SpikeAutoLogonSecret]::Store($password) -ne 0){throw 'Cannot protect clone autologon credential'}\n  $logon.DeleteValue('DefaultPassword',$false)}finally{$logon.Dispose();$password=$null;[Array]::Clear($random,0,$random.Length)}\n  $rotated=$true\n }\n $step=22\n $probe=Join-Path $base 'render.exe'\n Copy-Item -LiteralPath (Join-Path 'C:\\ProgramData\\Bivouac\\Image' 'hcs-render-probe.exe') -Destination $probe\n if((Get-FileHash -LiteralPath $probe -Algorithm SHA256).Hash -ine $data.sha256){exit 14}\n # Read only fixed display/GPU-PV readiness facts. Never emit PnP identities,\n # device names, driver paths, or arbitrary WMI/PowerShell diagnostics.\n $step=26\n $gpuStatus=[ordered]@{valid=$false;display_count=0;virtual_count=0;problem_code=0}\n $gpuBudget=[Diagnostics.Stopwatch]::StartNew()\n do {\n  try {\n   $nodes=@(Get-CimInstance -ClassName Win32_PnPEntity -Filter \"PNPClass='Display'\" -OperationTimeoutSec 10)\n   $drivers=@(Get-CimInstance -ClassName Win32_PnPSignedDriver -Filter \"DeviceClass='DISPLAY'\" -OperationTimeoutSec 10)\n   if($nodes.Count -gt 32 -or $drivers.Count -gt 32){throw 'device bound'}\n   $virtual=@($drivers | Where-Object InfName -ieq 'vrd.inf')\n   $problem=0\n   foreach($driver in $virtual){\n    $matching=@($nodes | Where-Object DeviceID -ieq $driver.DeviceID)\n    if($matching.Count -ne 1 -or $null -eq $matching[0].ConfigManagerErrorCode -or $matching[0].ConfigManagerErrorCode -gt 255){throw 'device status'}\n    $problem=[Math]::Max($problem,[int]$matching[0].ConfigManagerErrorCode)\n   }\n   $gpuStatus=[ordered]@{valid=$true;display_count=$nodes.Count;virtual_count=$virtual.Count;problem_code=$problem}\n  }catch{$gpuStatus=[ordered]@{valid=$false;display_count=0;virtual_count=0;problem_code=0};break}\n  if($gpuStatus.virtual_count -gt 0 -and $gpuStatus.problem_code -eq 0){break}\n  Start-Sleep -Milliseconds 500\n }while($gpuBudget.Elapsed.TotalSeconds -lt 30)\n # Inline so the existing script pin covers the interactive topology probe.\n $step=28\n $topologyScript=@'\n$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\ntry {\n Add-Type -ReferencedAssemblies @('System.Windows.Forms','System.Drawing') -TypeDefinition @\"\nusing System;\nusing System.Diagnostics;\nusing System.Drawing;\nusing System.Runtime.InteropServices;\nusing System.Threading;\nusing System.Windows.Forms;\nusing Microsoft.Win32;\npublic sealed class DesktopFacts {\n public bool topology_valid,virtual_equals_primary,probe_foreground,probe_on_primary,probe_input_received,security_window_found,security_on_primary;\n public uint active_display_count,primary_display_count,primary_width,primary_height,primary_adapter_kind;\n}\npublic static class DesktopProbe {\n [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct Display {\n  public uint cb;\n  [MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)] public string name;\n  [MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)] public string description;\n  public uint flags;\n  [MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)] public string id;\n  [MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)] public string key;\n }\n [StructLayout(LayoutKind.Sequential)] struct Rect { public int left,top,right,bottom; }\n [StructLayout(LayoutKind.Sequential)] struct Keyboard { public ushort vk,scan; public uint flags,time; public UIntPtr extra; }\n [StructLayout(LayoutKind.Sequential)] struct Mouse { public int x,y; public uint data,flags,time; public UIntPtr extra; }\n [StructLayout(LayoutKind.Explicit)] struct InputUnion { [FieldOffset(0)] public Keyboard keyboard; [FieldOffset(0)] public Mouse mouse; }\n [StructLayout(LayoutKind.Sequential)] struct Input { public uint type; public InputUnion value; }\n delegate bool WindowCallback(IntPtr window,IntPtr data);\n [DllImport(\"user32.dll\",CharSet=CharSet.Unicode)] static extern bool EnumDisplayDevices(string device,uint index,ref Display display,uint flags);\n [DllImport(\"user32.dll\")] static extern bool SetProcessDPIAware();\n [DllImport(\"user32.dll\")] static extern bool SetForegroundWindow(IntPtr window);\n [DllImport(\"user32.dll\")] static extern IntPtr GetForegroundWindow();\n [DllImport(\"user32.dll\")] static extern bool GetWindowRect(IntPtr window,out Rect bounds);\n [DllImport(\"user32.dll\")] static extern uint SendInput(uint count,Input[] input,int size);\n [DllImport(\"user32.dll\")] static extern bool EnumWindows(WindowCallback callback,IntPtr data);\n [DllImport(\"user32.dll\")] static extern bool EnumChildWindows(IntPtr parent,WindowCallback callback,IntPtr data);\n [DllImport(\"user32.dll\")] static extern bool IsWindowVisible(IntPtr window);\n [DllImport(\"user32.dll\")] static extern uint GetWindowThreadProcessId(IntPtr window,out uint pid);\n [DllImport(\"user32.dll\")] static extern bool PostMessage(IntPtr window,uint message,IntPtr wparam,IntPtr lparam);\n static bool Inside(IntPtr window,Rectangle area) {\n  Rect r; return GetWindowRect(window,out r) && r.right>r.left && r.bottom>r.top && r.left>=area.Left && r.top>=area.Top && r.right<=area.Right && r.bottom<=area.Bottom;\n }\n static void Pump(int milliseconds) {\n  Stopwatch budget=Stopwatch.StartNew();\n  while(budget.ElapsedMilliseconds<milliseconds) { Application.DoEvents(); Thread.Sleep(20); }\n }\n static bool SecurityProcess(IntPtr window) {\n  uint pid; GetWindowThreadProcessId(window,out pid);\n  if(pid==0 || pid>Int32.MaxValue) return false;\n  try { using(Process p=Process.GetProcessById((int)pid)) { return String.Equals(p.ProcessName,\"SecHealthUI\",StringComparison.OrdinalIgnoreCase); } } catch { return false; }\n }\n static IntPtr SecurityWindow() {\n  IntPtr found=IntPtr.Zero; int count=0;\n  EnumWindows(delegate(IntPtr window,IntPtr unused) {\n   if(++count>1024) return false;\n   if(!IsWindowVisible(window)) return true;\n   bool match=SecurityProcess(window); int children=0;\n   if(!match) EnumChildWindows(window,delegate(IntPtr child,IntPtr ignored) { if(++children>1024) return false; match=SecurityProcess(child); return !match; },IntPtr.Zero);\n   if(match) { found=window; return false; } return true;\n  },IntPtr.Zero);\n  return found;\n }\n static uint PrimaryAdapterKind(string hardware,string deviceKey) {\n  // Adapter entries expose their hardware ID directly. Consult the driver\n  // registry key only when that ID is empty; never override a supplied ID.\n  if(String.IsNullOrEmpty(hardware)) {\n   const string prefix=@\"\\Registry\\Machine\\\";\n   if(deviceKey!=null && deviceKey.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)) {\n    using(RegistryKey key=Registry.LocalMachine.OpenSubKey(deviceKey.Substring(prefix.Length))) {\n     hardware=key==null ? null : key.GetValue(\"MatchingDeviceId\") as string;\n    }\n   }\n  }\n  if(!String.IsNullOrEmpty(hardware) && hardware.Length<=1024) {\n   if(hardware.IndexOf(\"DA0A7802\",StringComparison.OrdinalIgnoreCase)>=0) return 1;\n   if(String.Equals(hardware,@\"ROOT\\APPSANDBOXVDD\",StringComparison.OrdinalIgnoreCase)) return 2;\n  }\n  return 3;\n }\n public static DesktopFacts Run() {\n  SetProcessDPIAware();\n  DesktopFacts facts=new DesktopFacts(); Screen primary=Screen.PrimaryScreen;\n  if(primary==null) throw new InvalidOperationException();\n  bool finished=false;\n  for(uint i=0;i<32;i++) {\n   Display d=new Display(); d.cb=(uint)Marshal.SizeOf(typeof(Display));\n   if(!EnumDisplayDevices(null,i,ref d,0)) { finished=true; break; }\n   if((d.flags&1)==0 || (d.flags&8)!=0) continue;\n   facts.active_display_count++;\n   if((d.flags&4)!=0) {\n    facts.primary_display_count++;\n    if(!String.Equals(d.name,primary.DeviceName,StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException();\n    facts.primary_adapter_kind=PrimaryAdapterKind(d.id,d.key);\n   }\n  }\n  if(!finished || primary.Bounds.Width<=0 || primary.Bounds.Height<=0 || primary.Bounds.Width>65536 || primary.Bounds.Height>65536) throw new InvalidOperationException();\n  facts.primary_width=(uint)primary.Bounds.Width; facts.primary_height=(uint)primary.Bounds.Height;\n  facts.virtual_equals_primary=SystemInformation.VirtualScreen.Equals(primary.Bounds);\n  using(Form window=new Form()) {\n   window.Text=\"Bivouac display probe\"; window.StartPosition=FormStartPosition.Manual; window.KeyPreview=true;\n   window.Size=new Size(Math.Min(320,primary.WorkingArea.Width),Math.Min(200,primary.WorkingArea.Height));\n   window.Location=new Point(primary.WorkingArea.Left+(primary.WorkingArea.Width-window.Width)/2,primary.WorkingArea.Top+(primary.WorkingArea.Height-window.Height)/2);\n   bool received=false; window.KeyDown+=delegate(object sender,KeyEventArgs e) { if(e.KeyCode==Keys.F24) received=true; };\n   window.Show(); window.BringToFront(); window.Activate(); SetForegroundWindow(window.Handle); Pump(500);\n   facts.probe_foreground=GetForegroundWindow()==window.Handle;\n   facts.probe_on_primary=Inside(window.Handle,primary.WorkingArea);\n   if(facts.probe_foreground) {\n    Input down=new Input(); down.type=1; down.value.keyboard.vk=0x87;\n    Input up=down; up.value.keyboard.flags=2;\n    bool sent=SendInput(2,new Input[]{down,up},Marshal.SizeOf(typeof(Input)))==2;\n    Stopwatch inputBudget=Stopwatch.StartNew();\n    while(!received && inputBudget.ElapsedMilliseconds<2000) Pump(20);\n    facts.probe_input_received=sent && received;\n   }\n   window.Close();\n  }\n  IntPtr security=IntPtr.Zero;\n  try {\n   ProcessStartInfo start=new ProcessStartInfo(\"windowsdefender:\"); start.UseShellExecute=true;\n   using(Process launched=Process.Start(start)) { }\n   Stopwatch securityBudget=Stopwatch.StartNew();\n   while(security==IntPtr.Zero && securityBudget.ElapsedMilliseconds<15000) { Pump(200); security=SecurityWindow(); }\n   facts.security_window_found=security!=IntPtr.Zero;\n   facts.security_on_primary=security!=IntPtr.Zero && Inside(security,primary.Bounds);\n  } catch { /* Windows Security facts are diagnostic, never a gate. */ }\n  finally { if(security!=IntPtr.Zero) PostMessage(security,0x10,IntPtr.Zero,IntPtr.Zero); }\n  facts.topology_valid=true; return facts;\n }\n}\n\"@\n $facts=[DesktopProbe]::Run()\n # No PresentOnly: phantom VDD nodes count too.\n $nodes=@(Get-PnpDevice | Where-Object { $_.Class -eq 'Display' -or $_.InstanceId -like 'ROOT\\APPSANDBOXVDD\\*' })\n if($nodes.Count -gt 256){throw 'device bound'}\n $vdd=0;$hyperv=0;$enabled=$true;$started=$true\n foreach($node in $nodes){\n  $ids=@((Get-PnpDeviceProperty -InstanceId $node.InstanceId -KeyName 'DEVPKEY_Device_HardwareIds').Data)\n  if($node.InstanceId -like 'ROOT\\APPSANDBOXVDD\\*' -or 'ROOT\\APPSANDBOXVDD' -in $ids){$vdd++}\n  if(@($ids | Where-Object {$_ -like '*DA0A7802*'}).Count){\n   $hyperv++\n   $problem=(Get-PnpDeviceProperty -InstanceId $node.InstanceId -KeyName 'DEVPKEY_Device_ProblemCode').Data\n   $status=(Get-PnpDeviceProperty -InstanceId $node.InstanceId -KeyName 'DEVPKEY_Device_DevNodeStatus').Data\n   if($null -eq $problem -or $problem -eq 22){$enabled=$false}\n   if($null -eq $problem -or $null -eq $status -or $problem -ne 0 -or !($status -band 8)){$started=$false}\n  }\n }\n $facts | Add-Member -NotePropertyName vdd_node_count -NotePropertyValue ([uint32]$vdd)\n $facts | Add-Member -NotePropertyName hyperv_video_enabled -NotePropertyValue ([bool]($hyperv -gt 0 -and $enabled))\n $facts | Add-Member -NotePropertyName hyperv_video_started -NotePropertyValue ([bool]($hyperv -gt 0 -and $started))\n $json=$facts | ConvertTo-Json -Compress\n if([Text.Encoding]::UTF8.GetByteCount($json) -gt 4096){throw 'report bound'}\n [IO.File]::WriteAllText((Join-Path $PSScriptRoot 'topology.pending'),$json,[Text.UTF8Encoding]::new($false))\n Move-Item -LiteralPath (Join-Path $PSScriptRoot 'topology.pending') -Destination (Join-Path $PSScriptRoot 'topology.json')\n exit 0\n} catch {exit 29}\n'@\n $topologyPath=Join-Path $base 'topology.ps1'\n [IO.File]::WriteAllText($topologyPath,$topologyScript,[Text.UTF8Encoding]::new($false))\n $topologyTask='bivouac-hcs-spike-topology'\n if(Get-ScheduledTask -TaskName $topologyTask -ErrorAction SilentlyContinue){exit 28}\n $principal=New-ScheduledTaskPrincipal -UserId ([Security.Principal.WindowsIdentity]::GetCurrent().Name) -LogonType Interactive -RunLevel Highest\n # Task Scheduler exposes a structured action field; every argument is fixed.\n $action=New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32\\WindowsPowerShell\\v1.0\\powershell.exe') -Argument '-NoProfile -NonInteractive -ExecutionPolicy Bypass -STA -File C:\\ProgramData\\Bivouac\\Image\\Probe\\topology.ps1' -WorkingDirectory $base\n $settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Minutes 1) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries\n Register-ScheduledTask -TaskName $topologyTask -Principal $principal -Action $action -Settings $settings | Out-Null\n try {\n  Start-ScheduledTask -TaskName $topologyTask\n  $result=Join-Path $base 'topology.json'\n  $budget=[Diagnostics.Stopwatch]::StartNew()\n  while(!(Test-Path -LiteralPath $result)){\n   if($budget.Elapsed.TotalSeconds -gt 50){exit 29}\n   $info=Get-ScheduledTaskInfo -TaskName $topologyTask\n   if($info.LastRunTime -gt (Get-Date).AddMinutes(-1) -and $info.LastTaskResult -eq 29){exit 29}\n   Start-Sleep -Milliseconds 200\n  }\n  if((Get-Item -LiteralPath $result).Length -gt 4096){exit 29}\n  $topology=Get-Content -LiteralPath $result -Raw | ConvertFrom-Json\n } finally {\n  Stop-ScheduledTask -TaskName $topologyTask -ErrorAction SilentlyContinue\n  Unregister-ScheduledTask -TaskName $topologyTask -Confirm:$false\n  foreach($name in @('topology.ps1','topology.json','topology.pending')){\n   $path=Join-Path $base $name\n   if(Test-Path -LiteralPath $path){Remove-Item -LiteralPath $path -Force}\n  }\n }\n $step=23\n $task='bivouac-hcs-spike-render'\n if(Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue){exit 15}\n $principal=New-ScheduledTaskPrincipal -UserId ([Security.Principal.WindowsIdentity]::GetCurrent().Name) -LogonType Interactive -RunLevel Highest\n $action=New-ScheduledTaskAction -Execute $probe -WorkingDirectory $base\n $settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Minutes 1) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries\n Register-ScheduledTask -TaskName $task -Principal $principal -Action $action -Settings $settings | Out-Null\n try {\n  $step=24\n  Start-ScheduledTask -TaskName $task\n  $result=Join-Path $base 'render.json'\n  $probeBudget=[Diagnostics.Stopwatch]::StartNew()\n  while(!(Test-Path -LiteralPath $result)) {if($probeBudget.Elapsed.TotalSeconds -gt 50){exit 16};Start-Sleep -Milliseconds 200}\n  $step=25\n  if((Get-Item -LiteralPath $result).Length -gt 4096){exit 25}\n  $observed=Get-Content -LiteralPath $result -Raw | ConvertFrom-Json\n  # Emit only fixed booleans/numbers; no guest-controlled text or filesystem dump.\n  $report=[ordered]@{credential_rotated=[bool]$rotated;guest_ready=$true;desktop_ready=($observed.desktop_ready -eq $true);hardware_d3d11=($observed.hardware_d3d11 -eq $true);presented=($observed.presented -eq $true);pixel_readback=($observed.pixel_readback -eq $true);stage=[uint32]$observed.stage;hresult=[uint32]$observed.hresult;vendor_id=[uint32]$observed.vendor_id;device_id=[uint32]$observed.device_id;adapter_count=[uint32]$observed.adapter_count;hardware_adapter_count=[uint32]$observed.hardware_adapter_count;default_vendor_id=[uint32]$observed.default_vendor_id;default_device_id=[uint32]$observed.default_device_id;gpu_device_diagnostics_valid=[bool]$gpuStatus.valid;display_device_count=[uint32]$gpuStatus.display_count;virtual_render_device_count=[uint32]$gpuStatus.virtual_count;virtual_render_problem_code=[uint32]$gpuStatus.problem_code}\n  foreach($field in @('topology_valid','virtual_equals_primary','hyperv_video_enabled','hyperv_video_started','probe_foreground','probe_on_primary','probe_input_received','security_window_found','security_on_primary')){\n   if($topology.$field -isnot [bool]){exit 29}\n   $report[$field]=[bool]$topology.$field\n  }\n  foreach($field in @('active_display_count','primary_display_count','primary_width','primary_height','primary_adapter_kind','vdd_node_count')){\n   $report[$field]=[uint32]$topology.$field\n  }\n  $report=$report | ConvertTo-Json -Compress -Depth 3\n  if([Text.Encoding]::UTF8.GetByteCount($report) -gt 8192){exit 25}\n  [Console]::Out.Write($report)\n  [Console]::Out.Flush()\n } finally {Unregister-ScheduledTask -TaskName $task -Confirm:$false}\n exit 0\n} catch {exit $step}\n"

const imageSanitize = "param($data)\n$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\ntry {\n if($env:COMPUTERNAME -ine $data.name -or $env:USERNAME -ine $data.user){exit 1}\n $setup=Get-ItemProperty 'HKLM:\\SYSTEM\\Setup'\n if($setup.SystemSetupInProgress -ne 0 -or $setup.OOBEInProgress -ne 0){exit 1}\n function Assert-Ordinary([string]$Path){\n  if(Test-Path -LiteralPath $Path){if((Get-Item -Force -LiteralPath $Path).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'link'}}\n }\n $base='C:\\ProgramData\\Bivouac\\Image'\n foreach($path in @('C:\\Windows',$base,'C:\\ProgramData','C:\\actions-runner')){Assert-Ordinary $path}\n if(!(Test-Path -LiteralPath 'C:\\actions-runner\\bin\\Runner.Listener.exe' -PathType Leaf)){exit 1}\n foreach($path in @('C:\\actions-runner\\.runner','C:\\actions-runner\\.credentials','C:\\actions-runner\\.credentials_rsaparams','C:\\actions-runner\\_work','C:\\actions-runner\\_diag')){if(Test-Path -LiteralPath $path){exit 1}}\n $probeBase='C:\\ProgramData\\Bivouac\\Image\\Probe'\n Assert-Ordinary $probeBase\n $entries=@(Get-ChildItem -Force -LiteralPath $probeBase)\n if($entries.Count -ne 2){exit 1}\n foreach($entry in $entries){if($entry.PSIsContainer -or $entry.Name -notin @('render.exe','render.json')){exit 1};Assert-Ordinary $entry.FullName}\n if((Get-FileHash -LiteralPath (Join-Path $probeBase 'render.exe') -Algorithm SHA256).Hash -ine $data.probe_sha256){exit 1}\n $reportPath=Join-Path $probeBase 'render.json'\n if((Get-Item -LiteralPath $reportPath).Length -gt 4096){exit 1}\n $observed=Get-Content -LiteralPath $reportPath -Raw|ConvertFrom-Json\n if(!$observed.hardware_d3d11 -or !$observed.presented -or !$observed.pixel_readback -or $observed.stage -ne 7 -or $observed.hresult -ne 0){exit 1}\n foreach($name in @('render.exe','render.json')){Remove-Item -Force -LiteralPath (Join-Path $probeBase $name)}\n Remove-Item -LiteralPath $probeBase\n $secretHelper=Join-Path $base 'hcs-spike-autologon.ps1'\n if((Get-FileHash -LiteralPath $secretHelper -Algorithm SHA256).Hash -ine $data.autologon_sha256){throw 'Autologon helper integrity differs'}\n . $secretHelper\n $random=New-Object byte[] 32\n $rng=[Security.Cryptography.RandomNumberGenerator]::Create()\n try{$rng.GetBytes($random)}finally{$rng.Dispose()}\n $password='Bv!'+[Convert]::ToBase64String($random)\n $secure=[Security.SecureString]::new()\n $characters=$password.ToCharArray()\n try{foreach($character in $characters){$secure.AppendChar($character)};$secure.MakeReadOnly()}finally{[Array]::Clear($characters,0,$characters.Length)}\n try{Set-LocalUser -Name $data.user -Password $secure}finally{$secure.Dispose()}\n $logon=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon',$true)\n try{\n  $logon.SetValue('AutoAdminLogon','1')\n  $logon.SetValue('DefaultUserName',$data.user)\n  $logon.SetValue('DefaultDomainName',$env:COMPUTERNAME)\n  if([SpikeAutoLogonSecret]::Store($password) -ne 0){throw 'Cannot protect clone autologon credential'}\n  $logon.DeleteValue('DefaultPassword',$false)\n  $logon.DeleteValue('AutoLogonCount',$false)\n }finally{$logon.Dispose();$password=$null;[Array]::Clear($random,0,$random.Length)}\n foreach($path in @('C:\\Windows\\Panther\\Unattend\\unattend.xml','C:\\Windows\\Panther\\Unattend\\specialize.ps1','C:\\Windows\\Panther\\Unattend\\setup-step.json','C:\\Windows\\Panther\\unattend.xml','C:\\Windows\\System32\\Sysprep\\unattend.xml')){\n  $parent=Split-Path -Parent $path;Assert-Ordinary $parent;Assert-Ordinary $path\n  if(Test-Path -LiteralPath $path -PathType Leaf){Remove-Item -Force -LiteralPath $path}\n }\n # No adapter delivery belongs in an image. The build agent logs separately;\n # delete its open, delete-shared log before scheduling shutdown.\n foreach($directory in @('C:\\ProgramData\\Bivouac\\Guest','C:\\ProgramData\\Bivouac\\Agent')){\n  Assert-Ordinary $directory\n  if(Test-Path -LiteralPath $directory){\n   $entries=@(Get-ChildItem -Force -LiteralPath $directory)\n   if($entries.Count -gt 8){exit 1}\n   foreach($entry in $entries){\n    if($entry.PSIsContainer -or $entry.Name -notin @('agent.log','agent.log.1','.receive.lock')){exit 1}\n    Assert-Ordinary $entry.FullName;Remove-Item -Force -LiteralPath $entry.FullName\n   }\n   if($directory -like '*\\Guest'){Remove-Item -LiteralPath $directory}\n  }\n }\n if(!(Get-ScheduledTask -TaskName 'bivouac-guest-agent' -ErrorAction SilentlyContinue)){exit 1}\n $marker=Join-Path $base 'hcs-spike-prepared.json';Assert-Ordinary $marker\n if(Test-Path -LiteralPath $marker){exit 1}\n $metadata=[ordered]@{name=$data.name;user=$data.user;probe_sha256=$data.probe_sha256;validation_sha256=$data.validation_sha256;autologon_sha256=$data.autologon_sha256}\n [IO.File]::WriteAllText($marker,($metadata|ConvertTo-Json -Compress),[Text.UTF8Encoding]::new($false))\n # Keep the agent's logon task for the next cold boot.\n & 'C:\\Windows\\System32\\shutdown.exe' @('/s','/t','5','/d','p:0:0') *> $null\n if($LASTEXITCODE){exit 1}\n [Console]::Out.Write('sanitized-shutdown-scheduled');[Console]::Out.Flush()\n exit 0\n}catch{exit 1}\n"

const autologonSecret = "$ErrorActionPreference='Stop'\nAdd-Type -TypeDefinition @\"\nusing System;using System.Runtime.InteropServices;\npublic static class SpikeAutoLogonSecret {\n [StructLayout(LayoutKind.Sequential)] struct Unicode {public ushort Length,MaximumLength;public IntPtr Buffer;}\n [StructLayout(LayoutKind.Sequential)] struct Attributes {public uint Length;public IntPtr Root,ObjectName;public uint Flags;public IntPtr Descriptor,Quality;}\n [DllImport(\"advapi32.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint LsaOpenPolicy(IntPtr system,ref Attributes attributes,uint access,out IntPtr policy);\n [DllImport(\"advapi32.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint LsaStorePrivateData(IntPtr policy,ref Unicode name,ref Unicode value);\n [DllImport(\"advapi32.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint LsaClose(IntPtr policy);\n public static uint Store(string password) {\n  if(password==null || password.Length==0 || password.Length>512)return 87;\n  var a=new Attributes();a.Length=(uint)Marshal.SizeOf(typeof(Attributes));IntPtr policy;\n  uint error=LsaOpenPolicy(IntPtr.Zero,ref a,0x20,out policy);if(error!=0)return error;\n  var name=new Unicode();var secret=new Unicode();\n  try {\n   string label=\"DefaultPassword\";name.Length=(ushort)(label.Length*2);name.MaximumLength=(ushort)(name.Length+2);name.Buffer=Marshal.StringToHGlobalUni(label);\n   secret.Length=(ushort)(password.Length*2);secret.MaximumLength=(ushort)(secret.Length+2);secret.Buffer=Marshal.StringToHGlobalUni(password);\n   return LsaStorePrivateData(policy,ref name,ref secret);\n  } finally {if(secret.Buffer!=IntPtr.Zero)Marshal.ZeroFreeGlobalAllocUnicode(secret.Buffer);if(name.Buffer!=IntPtr.Zero)Marshal.FreeHGlobal(name.Buffer);LsaClose(policy);}\n }\n}\n\"@\n"

const inspectDisk = "$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\n$image=$null;$disk=$null;$partition=$null;$step=10;$code=0\n$facts=[ordered]@{failure_step=0;system_hive_error=[uint32]::MaxValue;software_hive_error=[uint32]::MaxValue;sam_hive_error=[uint32]::MaxValue;system_setup_in_progress=[uint32]::MaxValue;oobe_in_progress=[uint32]::MaxValue;setup_phase=[uint32]::MaxValue;image_state_kind='unknown';unattend_pointer_kind='present_or_unknown';answer_directory_empty=$false;panther_answer_present=$false;panther_answer=$null;agent_present=$false;agent_sha256='';agent_task_present=$false;vdd_present=$null;runner_state='invalid';runner_residue=@{};runner_version='';bivouac_present=$false;bivouac_subdirectories=@();guest_state_present=$false;guest_user_exists=$null;guest_setup_step=0;guest_setup_failed=$false}\ntry {\n $data=[Console]::In.ReadToEnd()|ConvertFrom-Json\n if($data.instance_id -cnotmatch '^[0-9a-f]{32}$'){throw 'identity'}\n $child=Join-Path $data.root $data.instance_id\n $expectedDisk=Join-Path $child 'disk.vhdx'\n $marker=Get-Content -LiteralPath (Join-Path $child 'owner.json') -Raw|ConvertFrom-Json\n if($data.disk -cne $expectedDisk -or $marker.build_id -cne $data.instance_id -or $marker.workspace -cne $child){throw 'ownership'}\n foreach($path in @($child,$expectedDisk)){if((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'link'}}\n if((Get-DiskImage -ImagePath $expectedDisk).Attached){throw 'attached'}\n $step=20\n $null=Add-Type -TypeDefinition @\"\nusing System;using System.Text;using System.Runtime.InteropServices;\npublic static class FactoryInspection {\n [DllImport(\"offreg.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint OROpenKey(IntPtr hive,string key,out IntPtr opened);\n [DllImport(\"offreg.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint ORCloseKey(IntPtr key);\n public static bool Exists(IntPtr hive,string key) {IntPtr opened;uint error=OROpenKey(hive,key,out opened);if(error==2)return false;if(error!=0)throw new InvalidOperationException();try{return true;}finally{ORCloseKey(opened);}}\n public static string Text(IntPtr hive,string key,string value) {uint type,size=2048;byte[] data=new byte[2048];uint error=ORGetValue(hive,key,value,out type,data,ref size);if(error!=0 || (type!=1 && type!=2) || size<2 || size>2048) return \"\";return Encoding.Unicode.GetString(data,0,(int)size).TrimEnd('\\0');}\n [DllImport(\"offreg.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] public static extern uint OROpenHive(string path,out IntPtr hive);\n [DllImport(\"offreg.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] public static extern uint ORCloseHive(IntPtr hive);\n [DllImport(\"offreg.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint ORGetValue(IntPtr hive,string key,string value,out uint type,byte[] data,ref uint size);\n public static uint Number(IntPtr hive,string key,string value) {uint type,size=4;byte[] data=new byte[4];uint error=ORGetValue(hive,key,value,out type,data,ref size);return error==0 && type==4 && size==4?BitConverter.ToUInt32(data,0):uint.MaxValue;}\n public static string State(IntPtr hive) {uint type,size=256;byte[] data=new byte[256];uint error=ORGetValue(hive,\"Microsoft\\\\Windows\\\\CurrentVersion\\\\Setup\\\\State\",\"ImageState\",out type,data,ref size);if(error!=0 || type!=1 || size>256 || size<2)return \"unknown\";return Encoding.Unicode.GetString(data,0,(int)size).TrimEnd('\\0')==\"IMAGE_STATE_GENERALIZE_RESEAL_TO_OOBE\"?\"generalized_to_oobe\":\"other\";}\n public static string Pointer(IntPtr hive) {uint type,size=0;uint error=ORGetValue(hive,\"Setup\",\"UnattendFile\",out type,null,ref size);if(error==2)return \"absent\";if(error!=0 || type!=1 || size>2)return \"present_or_unknown\";byte[] data=new byte[size];error=ORGetValue(hive,\"Setup\",\"UnattendFile\",out type,data,ref size);return error==0 && Array.TrueForAll(data,b=>b==0)?\"empty\":\"present_or_unknown\";}\n}\n\"@\n $mount=Join-Path $child 'inspect-mount'\n if(Test-Path -LiteralPath $mount){throw 'mount path'}\n $null=New-Item -ItemType Directory -Path $mount\n $access=$mount+'\\'\n try {\n  $step=30\n  $image=Mount-DiskImage -ImagePath $expectedDisk -Access ReadWrite -NoDriveLetter -PassThru\n  $disk=$image|Get-Disk\n  $partition=Get-Partition -DiskNumber $disk.Number|Sort-Object Size -Descending|Select-Object -First 1\n  $null=Add-PartitionAccessPath -DiskNumber $disk.Number -PartitionNumber $partition.PartitionNumber -AccessPath $access\n  if($data.mode -eq 'setup'){\n   $step=90;Read-SetupStep $mount $facts\n  }else{\n   $step=40\n   foreach($relative in @('Windows','Windows\\Panther','Windows\\System32','Windows\\System32\\config','Windows\\System32\\config\\SYSTEM','Windows\\System32\\config\\SOFTWARE')){\n    $path=Join-Path $mount $relative\n    if(!(Test-Path -LiteralPath $path) -or ((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'child Windows path'}\n   }\n   $system=Join-Path $mount 'Windows\\System32\\config\\SYSTEM'\n   $software=Join-Path $mount 'Windows\\System32\\config\\SOFTWARE'\n   if((Get-Item -LiteralPath $system).Length -gt 256MB){throw 'system hive bound'}\n   $hive=[IntPtr]::Zero\n   $facts.system_hive_error=[FactoryInspection]::OROpenHive($system,[ref]$hive)\n   if($facts.system_hive_error -eq 0){try{\n    $facts.system_setup_in_progress=[FactoryInspection]::Number($hive,'Setup','SystemSetupInProgress')\n    $facts.oobe_in_progress=[FactoryInspection]::Number($hive,'Setup','OOBEInProgress')\n    $facts.setup_phase=[FactoryInspection]::Number($hive,'Setup','SetupPhase')\n    $facts.unattend_pointer_kind=[FactoryInspection]::Pointer($hive)\n    try{\n     $current=[FactoryInspection]::Number($hive,'Select','Current')\n     if($current -lt 1 -or $current -gt 999){throw 'control set'}\n     $control='ControlSet'+$current.ToString('000')\n     $facts.vdd_present=[FactoryInspection]::Exists($hive,($control+'\\Enum\\ROOT\\APPSANDBOXVDD'))\n    }catch{}\n   }finally{[void][FactoryInspection]::ORCloseHive($hive)}}\n   $step=50\n   $hive=[IntPtr]::Zero\n   $facts.software_hive_error=[FactoryInspection]::OROpenHive($software,[ref]$hive)\n   if($facts.software_hive_error -eq 0){try{$facts.image_state_kind=[FactoryInspection]::State($hive)}finally{[void][FactoryInspection]::ORCloseHive($hive)}}\n   $step=60\n   $answer=Join-Path $mount 'Windows\\Panther\\Unattend'\n   if(!(Test-Path -LiteralPath $answer)){$facts.answer_directory_empty=$true}else{\n    $item=Get-Item -Force -LiteralPath $answer\n    $facts.answer_directory_empty=($item.PSIsContainer -and !($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -and !@(Get-ChildItem -Force -LiteralPath $answer|Select-Object -First 1).Count)\n   }\n   try{$facts.panther_answer_present=Test-Path -LiteralPath (Join-Path $mount 'Windows\\Panther\\unattend.xml')}catch{}\n   Read-PantherAnswerFacts $mount $data.guest_user $facts\n   $step=70;Read-FactoryFiles $mount $facts\n   $step=80\n   if($data.guest_user -notmatch '^[a-zA-Z0-9_-]{1,20}$'){throw 'guest user'}\n   try{\n    $sam=Join-Path $mount 'Windows\\System32\\config\\SAM'\n    if(!(Test-OrdinaryFilePath $sam)){throw 'SAM unavailable'}\n    $hive=[IntPtr]::Zero\n    $facts.sam_hive_error=[FactoryInspection]::OROpenHive($sam,[ref]$hive)\n    if($facts.sam_hive_error -eq 0){try{$facts.guest_user_exists=[FactoryInspection]::Exists($hive,('SAM\\Domains\\Account\\Users\\Names\\'+$data.guest_user))}finally{[void][FactoryInspection]::ORCloseHive($hive)}}\n   }catch{$facts.guest_user_exists=$null}\n  }\n }finally{\n  if($image){try{if($partition){$null=Remove-PartitionAccessPath -DiskNumber $disk.Number -PartitionNumber $partition.PartitionNumber -AccessPath $access}}finally{$null=Dismount-DiskImage -ImagePath $expectedDisk}}\n }\n $step=95\n if((Get-DiskImage -ImagePath $expectedDisk).Attached){throw 'still attached'}\n $null=Remove-Item -LiteralPath $mount\n}catch{$code=$step;$facts.failure_step=$step}\n[Console]::Out.WriteLine('BIVOUAC_IMAGE_RESULT')\n[Console]::Out.WriteLine(($facts|ConvertTo-Json -Compress -Depth 8))\nexit $code\n"

const detachDisk = "$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\ntry{\n $data=[Console]::In.ReadToEnd()|ConvertFrom-Json\n if($data.instance_id -cnotmatch '^[0-9a-f]{32}$'){exit 1}\n $child=Join-Path $data.root $data.instance_id\n $marker=Get-Content -LiteralPath (Join-Path $child 'owner.json') -Raw|ConvertFrom-Json\n $disk=Join-Path $child 'disk.vhdx'\n if($data.disk -cne $disk -or $marker.build_id -cne $data.instance_id -or $marker.workspace -cne $child){exit 1}\n foreach($path in @($child,$disk)){if((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){exit 1}}\n if((Get-DiskImage -ImagePath $disk).Attached){$null=Dismount-DiskImage -ImagePath $disk}\n if((Get-DiskImage -ImagePath $disk).Attached){exit 1}\n exit 0\n}catch{exit 1}\n"

const runnerCheck = "function Assert-CleanRunner([string]$Runner) {\n if(!(Test-Path -LiteralPath $Runner)){return $false}\n $directory=Get-Item -Force -LiteralPath $Runner\n if(!$directory.PSIsContainer -or ($directory.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'runner directory'}\n foreach($entry in @(Get-ChildItem -Force -LiteralPath $Runner)){\n  if($entry.Name -eq '.runner' -or $entry.Name -like '.credentials*'){throw 'configured runner'}\n  if($entry.Name -in @('_work','_diag')){\n   if(!$entry.PSIsContainer -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -or @(Get-ChildItem -Force -LiteralPath $entry.FullName | Select-Object -First 1).Count){throw 'runner residue'}\n  }\n }\n foreach($part in @('bin','bin\\Runner.Listener.exe','config.cmd','run.cmd')){\n  $path=Join-Path $Runner $part\n  if(!(Test-Path -LiteralPath $path)){throw 'runner incomplete'}\n  $item=Get-Item -Force -LiteralPath $path\n  if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or ($part -eq 'bin' -and !$item.PSIsContainer) -or ($part -ne 'bin' -and ($item.PSIsContainer -or $item.Length -eq 0))){throw 'runner incomplete'}\n }\n return $true\n}\n"

const offlineFiles = "# Public filesystem facts only. Do not read runner registration files, policy\n# backup contents, authorized keys or credentials.\nfunction Test-OrdinaryFilePath([string]$Path){\n try{return !((Get-Item -Force -LiteralPath $Path).Attributes -band [IO.FileAttributes]::ReparsePoint)}catch{return $false}\n}\nfunction Read-RunnerFacts([string]$Runner,$Facts){\n $Facts.runner_state='invalid';$Facts.runner_residue=@{}\n if(!(Test-Path -LiteralPath $Runner)){$Facts.runner_state='absent';return}\n $directory=Get-Item -Force -LiteralPath $Runner\n if(!$directory.PSIsContainer -or !(Test-OrdinaryFilePath $Runner)){return}\n $configured=$false;$residue=$false;$invalid=$false\n foreach($entry in Get-ChildItem -Force -LiteralPath $Runner){\n  if($entry.Name -eq '.runner' -or $entry.Name -like '.credentials*'){$configured=$true}\n  if($entry.Name -in @('_work','_diag')){\n   if(!$entry.PSIsContainer -or !(Test-OrdinaryFilePath $entry.FullName)){$invalid=$true;continue}\n   $fact=@{entries=@();omitted_names=0;truncated=$false}\n   foreach($child in Get-ChildItem -Force -LiteralPath $entry.FullName){\n    $residue=$true\n    if($child.Name -notmatch '^[A-Za-z0-9_. -]{1,128}$'){$fact.omitted_names++;continue}\n    if($fact.entries.Count -ge 64){$fact.truncated=$true;continue}\n    $fact.entries+=@{name=$child.Name;directory=[bool]$child.PSIsContainer}\n   }\n   $Facts.runner_residue[$entry.Name]=$fact\n  }\n }\n if($configured){$Facts.runner_state='configured';return}\n if($invalid){return}\n $Facts.runner_state='incomplete'\n foreach($part in @('bin','bin\\Runner.Listener.exe','config.cmd','run.cmd')){\n  $path=Join-Path $Runner $part\n  if(!(Test-Path -LiteralPath $path)){return}\n  $item=Get-Item -Force -LiteralPath $path\n  if(!(Test-OrdinaryFilePath $path)){$Facts.runner_state='invalid';return}\n  if(($part -eq 'bin' -and !$item.PSIsContainer) -or ($part -ne 'bin' -and ($item.PSIsContainer -or $item.Length -eq 0))){return}\n }\n $Facts.runner_state=if($residue){'residue'}else{'unconfigured'}\n}\nfunction Read-FactoryFiles([string]$Root,$Facts) {\n # These paths guard the Guest-state refusal; unknown access fails closed.\n foreach($relative in @('ProgramData','ProgramData\\Bivouac')){\n  $path=Join-Path $Root $relative\n  if((Test-Path -LiteralPath $path) -and !(Test-OrdinaryFilePath $path)){throw 'guest state path'}\n }\n $bivouac=Join-Path $Root 'ProgramData\\Bivouac'\n $Facts.guest_state_present=Test-Path -LiteralPath (Join-Path $bivouac 'Guest')\n Read-RunnerFacts (Join-Path $Root 'actions-runner') $Facts\n $agentDirectory=Join-Path $Root 'Program Files\\Bivouac'\n $agent=Join-Path $agentDirectory 'bivouac.exe'\n foreach($path in @((Join-Path $Root 'Program Files'),$agentDirectory)){\n  if((Test-Path -LiteralPath $path) -and !(Test-OrdinaryFilePath $path)){throw 'agent install path'}\n }\n # Any existing install directory, even incomplete, refuses template reuse.\n $Facts.agent_present=Test-Path -LiteralPath $agentDirectory\n $Facts.agent_task_present=Test-Path -LiteralPath (Join-Path $Root 'Windows\\System32\\Tasks\\bivouac-guest-agent')\n $Facts.agent_sha256=''\n if(Test-Path -LiteralPath $agent){\n  $file=Get-Item -Force -LiteralPath $agent\n  if($file.PSIsContainer -or $file.Length -gt 128MB -or !(Test-OrdinaryFilePath $agent)){throw 'agent install file'}\n  $Facts.agent_sha256=(Get-FileHash -LiteralPath $agent -Algorithm SHA256).Hash.ToLowerInvariant()\n }\n # Runner version and names below are informational public metadata.\n $runner=Join-Path $Root 'actions-runner'\n try{if((Test-OrdinaryFilePath $runner) -and (Test-OrdinaryFilePath (Join-Path $runner 'bin'))){\n  $listener=Join-Path $runner 'bin\\Runner.Listener.exe'\n  if((Test-Path -LiteralPath $listener -PathType Leaf) -and (Test-OrdinaryFilePath $listener)){\n   $version=(Get-Item -LiteralPath $listener).VersionInfo.ProductVersion\n   if($version -match '^\\d{1,4}\\.\\d{1,4}\\.\\d{1,4}$'){$Facts.runner_version=$version}\n  }\n }}catch{}\n try{$Facts.bivouac_present=Test-Path -LiteralPath $bivouac}catch{}\n $Facts.bivouac_subdirectories=@()\n try{if($Facts.bivouac_present){\n  foreach($directory in (Get-ChildItem -Force -Directory -LiteralPath $bivouac|Select-Object -First 32)){\n   if($directory.Name -match '^[a-zA-Z0-9_.-]{1,128}$'){$Facts.bivouac_subdirectories+=$directory.Name}\n  }\n }}catch{}\n}\nfunction Read-PantherAnswerFacts([string]$Root,[string]$GuestUser,$Facts){\n try{\n  $path=Join-Path $Root 'Windows\\Panther\\unattend.xml'\n  $item=Get-Item -Force -LiteralPath $path\n  if($item.PSIsContainer -or $item.Length -gt 1MB -or !(Test-OrdinaryFilePath $path)){return}\n  $settings=New-Object Xml.XmlReaderSettings\n  $settings.DtdProcessing=[Xml.DtdProcessing]::Prohibit;$settings.XmlResolver=$null;$settings.MaxCharactersInDocument=1MB\n  $reader=[Xml.XmlReader]::Create($path,$settings)\n  try{$xml=New-Object Xml.XmlDocument;$xml.XmlResolver=$null;$xml.Load($reader)}finally{$reader.Dispose()}\n  $fact=@{specialize_pass=$false;oobe_system_pass=$false;guest_local_account=$false;autologon_present=$false;autologon_guest_user=$false}\n  foreach($pass in $xml.SelectNodes('/*[local-name()=\"unattend\"]/*[local-name()=\"settings\"]')){\n   if($pass.GetAttribute('pass') -eq 'specialize'){$fact.specialize_pass=$true}\n   if($pass.GetAttribute('pass') -eq 'oobeSystem'){$fact.oobe_system_pass=$true}\n  }\n  foreach($name in $xml.SelectNodes('//*[local-name()=\"LocalAccount\"]/*[local-name()=\"Name\"]')){if($name.InnerText -eq $GuestUser){$fact.guest_local_account=$true}}\n  foreach($autologon in $xml.SelectNodes('//*[local-name()=\"AutoLogon\"]')){\n   $fact.autologon_present=$true\n   foreach($name in $autologon.SelectNodes('./*[local-name()=\"Username\"]')){if($name.InnerText -eq $GuestUser){$fact.autologon_guest_user=$true}}\n  }\n  $Facts.panther_answer=$fact\n }catch{}\n}\n\nfunction Read-SetupStep([string]$Root,$Facts){\n $path=Join-Path $Root 'Windows\\Panther\\Unattend\\setup-step.json'\n if(!(Test-Path -LiteralPath $path)){return}\n foreach($relative in @('Windows','Windows\\Panther','Windows\\Panther\\Unattend','Windows\\Panther\\Unattend\\setup-step.json')){\n  if((Get-Item -Force -LiteralPath (Join-Path $Root $relative)).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'setup path'}\n }\n $item=Get-Item -Force -LiteralPath $path\n if($item.PSIsContainer -or $item.Length -gt 32768){throw 'setup status bound'}\n $status=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json\n if($status.step -isnot [int] -or $status.step -lt 10 -or $status.step -gt 100 -or $status.failed -isnot [bool]){throw 'setup status'}\n $Facts.guest_setup_step=[uint32]$status.step;$Facts.guest_setup_failed=$status.failed\n if($null -ne $status.video){\n  $Facts.guest_setup_video=Read-VideoDiagnostics $status.video\n }\n}\n"

const offlinePayload = "# Mounted-volume operations only; callers own the disk mount and child proof.\nfunction Set-OfflineOwner([string]$Path,[Security.Principal.SecurityIdentifier]$Owner) {\n if((Get-Acl -LiteralPath $Path).GetOwner([Security.Principal.SecurityIdentifier]).Equals($Owner)){return}\n if(!('BivouacOfflineOwner' -as [type])){\n  Add-Type -TypeDefinition @\"\nusing System;using System.Diagnostics;using System.Runtime.InteropServices;using System.Security.Principal;\npublic static class BivouacOfflineOwner {\n [StructLayout(LayoutKind.Sequential)] struct Privilege {public uint count;public uint low;public int high;public uint attributes;}\n [DllImport(\"advapi32.dll\",SetLastError=true)] static extern bool OpenProcessToken(IntPtr process,uint access,out IntPtr token);\n [DllImport(\"advapi32.dll\",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool LookupPrivilegeValue(string system,string name,out long luid);\n [DllImport(\"advapi32.dll\",SetLastError=true)] static extern bool AdjustTokenPrivileges(IntPtr token,bool disable,ref Privilege state,uint length,out Privilege previous,out uint returned);\n [DllImport(\"advapi32.dll\",CharSet=CharSet.Unicode)] static extern uint SetNamedSecurityInfo(string path,int kind,uint info,byte[] owner,IntPtr group,IntPtr dacl,IntPtr sacl);\n [DllImport(\"kernel32.dll\")] static extern bool CloseHandle(IntPtr handle);\n public static uint Set(string path,SecurityIdentifier owner) {\n  byte[] sid=new byte[owner.BinaryLength];owner.GetBinaryForm(sid,0);\n  uint result=SetNamedSecurityInfo(path,1,1,sid,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero);\n  if(result==0)return 0;\n  // A guest repository is normally owned by TrustedInstaller. An elevated\n  // administrator has SeRestorePrivilege, but it must be enabled explicitly.\n  IntPtr token;if(!OpenProcessToken(Process.GetCurrentProcess().Handle,0x28,out token))return (uint)Marshal.GetLastWin32Error();\n  try {\n   long luid;if(!LookupPrivilegeValue(null,\"SeRestorePrivilege\",out luid))return (uint)Marshal.GetLastWin32Error();\n   Privilege next=new Privilege{count=1,low=(uint)luid,high=(int)(luid>>32),attributes=2};Privilege previous;uint length;\n   if(!AdjustTokenPrivileges(token,false,ref next,(uint)Marshal.SizeOf(typeof(Privilege)),out previous,out length))return (uint)Marshal.GetLastWin32Error();\n   uint error=(uint)Marshal.GetLastWin32Error();if(error!=0)return error;\n   try{return SetNamedSecurityInfo(path,1,1,sid,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero);}\n   finally{Privilege ignored;uint returned;AdjustTokenPrivileges(token,false,ref previous,(uint)Marshal.SizeOf(typeof(Privilege)),out ignored,out returned);}\n  }finally{CloseHandle(token);}\n }\n}\n\"@\n }\n $ownerError=[BivouacOfflineOwner]::Set($Path,$Owner)\n if($ownerError -ne 0){throw ('guest owner assignment '+$ownerError)}\n}\nfunction Assert-OfflinePath([string]$Root,[string]$Path) {\n $rootPath=[IO.Path]::GetFullPath($Root).TrimEnd('\\')\n $pathValue=[IO.Path]::GetFullPath($Path)\n if(!$pathValue.StartsWith($rootPath+'\\',[StringComparison]::OrdinalIgnoreCase) -and $pathValue -ine $rootPath){throw 'offline path boundary'}\n $current=$pathValue\n # The root is the volume access path this build mounted, itself a mount\n # point (a reparse point); every component below it must be ordinary.\n while($current.Length -gt $rootPath.Length){\n  if(Test-Path -LiteralPath $current){\n   if((Get-Item -Force -LiteralPath $current).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'offline link'}\n  }\n  $current=Split-Path -Parent $current\n }\n}\nfunction New-OfflineDirectory([string]$Root,[string]$Path) {\n Assert-OfflinePath $Root $Path\n if(!(Test-Path -LiteralPath $Path)){New-Item -ItemType Directory -Path $Path -Force | Out-Null}\n if(!(Get-Item -LiteralPath $Path).PSIsContainer){throw 'offline directory'}\n}\nfunction Copy-OfflineDrivers([string]$Mount,[string]$Snapshot,$Plan) {\n $system=Join-Path $Mount 'Windows\\System32'\n New-OfflineDirectory $Mount $system\n foreach($relative in @('HostDriverStore','HostDriverStore\\FileRepository')){\n  $path=Join-Path $system $relative\n  Assert-OfflinePath $Mount $path\n  if(!(Test-Path -LiteralPath $path)){\n   $owner=(Get-Acl -LiteralPath (Split-Path -Parent $path)).GetOwner([Security.Principal.SecurityIdentifier])\n   New-OfflineDirectory $Mount $path\n   Set-OfflineOwner $path $owner\n  }\n }\n $repository=Join-Path $system 'HostDriverStore\\FileRepository'\n $parentACL=Get-Acl -LiteralPath $repository\n $count=0;[long]$bytes=0;$names=@{}\n foreach($driver in $Plan){\n  if($driver.name -notmatch '^[A-Za-z0-9_.-]{1,160}$' -or $driver.name -in @('.','..') -or $names.ContainsKey($driver.name)){throw 'driver directory name'}\n  $names[$driver.name]=$true\n  $source=Join-Path $Snapshot ([string]$count);$count++\n  if($count -gt 8){throw 'driver count'}\n  Assert-OfflinePath $Snapshot $source\n  # Verify the exact snapshot inventory, so missing files and unexpected links\n  # cannot become an apparently successful partial installation.\n  $files=@{};$directories=@{};$queue=[Collections.Generic.Queue[string]]::new();$queue.Enqueue($source);$entries=0\n  while($queue.Count){foreach($item in @(Get-ChildItem -LiteralPath ($queue.Dequeue()) -Force)){\n   $entries++;if($entries -gt 16384 -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'snapshot link or bound'}\n   $relative=$item.FullName.Substring($source.Length+1)\n   if($item.PSIsContainer){$directories[$relative]=$true;$queue.Enqueue($item.FullName)}else{$files[$relative]=$item}\n  }}\n  $expected=@($driver.files.PSObject.Properties)\n  if(!$expected.Count -or $expected.Count -gt 8192 -or $files.Count -ne $expected.Count -or $directories.Count -ne @($driver.directories).Count){throw 'partial snapshot'}\n  foreach($directory in $driver.directories){if(!$directories.ContainsKey($directory)){throw 'partial directory'}}\n  $target=Join-Path $repository $driver.name;$temporary=$target+'.bivouac-staging'\n  foreach($path in @($target,$temporary)){Assert-OfflinePath $Mount $path;if(Test-Path -LiteralPath $path){throw 'existing driver tree'}}\n  try {\n   New-OfflineDirectory $Mount $temporary\n   # Only owner and inherited guest permissions come from the guest parent.\n   # No host ACL is ever copied. New files inherit from the temporary tree.\n   $acl=Get-Acl -LiteralPath $temporary\n   $acl.SetAccessRuleProtection($false,$false)\n   foreach($rule in @($acl.Access)){if(!$rule.IsInherited){[void]$acl.RemoveAccessRuleSpecific($rule)}}\n   Set-Acl -LiteralPath $temporary -AclObject $acl\n   Set-OfflineOwner $temporary ($parentACL.GetOwner([Security.Principal.SecurityIdentifier]))\n   foreach($directory in $driver.directories){New-OfflineDirectory $temporary (Join-Path $temporary $directory)}\n   foreach($entry in $expected){\n    if(!$files.ContainsKey($entry.Name) -or $entry.Value -notmatch '^[0-9a-f]{64}$'){throw 'snapshot inventory'}\n    $inputFile=$files[$entry.Name];$bytes+=$inputFile.Length;if($bytes -gt 2GB){throw 'driver bytes'}\n    if((Get-FileHash -LiteralPath $inputFile.FullName -Algorithm SHA256).Hash -ine $entry.Value){throw 'snapshot hash'}\n    $outputFile=Join-Path $temporary $entry.Name;Assert-OfflinePath $temporary $outputFile\n    [IO.File]::Copy($inputFile.FullName,$outputFile,$false)\n    if((Get-FileHash -LiteralPath $outputFile -Algorithm SHA256).Hash -ine $entry.Value){throw 'offline driver hash'}\n    Set-OfflineOwner $outputFile ($parentACL.GetOwner([Security.Principal.SecurityIdentifier]))\n   }\n   foreach($directory in $driver.directories){$path=Join-Path $temporary $directory;Set-OfflineOwner $path ($parentACL.GetOwner([Security.Principal.SecurityIdentifier]))}\n   # Rename on the mounted volume publishes only the complete verified tree.\n   [IO.Directory]::Move($temporary,$target)\n  } finally {if(Test-Path -LiteralPath $temporary){Assert-OfflinePath $Mount $temporary;Remove-Item -LiteralPath $temporary -Recurse -Force}}\n }\n}\nfunction Install-OfflineAgent([string]$Mount,[string]$Source,[string]$Hash) {\n $directory=Join-Path $Mount 'Program Files\\Bivouac'\n Assert-OfflinePath $Mount $directory\n if(Test-Path -LiteralPath $directory){throw 'agent install already exists'}\n New-OfflineDirectory $Mount $directory\n $acl=[Security.AccessControl.DirectorySecurity]::new()\n $acl.SetSecurityDescriptorSddlForm('O:BAD:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)(A;OICI;FA;;;S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464)(A;OICI;0x1200a9;;;BU)')\n Set-Acl -LiteralPath $directory -AclObject $acl\n $target=Join-Path $directory 'bivouac.exe'\n [IO.File]::Copy($Source,$target,$false)\n $fileACL=[Security.AccessControl.FileSecurity]::new()\n $fileACL.SetSecurityDescriptorSddlForm('O:BAD:P(A;;FA;;;SY)(A;;FA;;;BA)(A;;FA;;;S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464)(A;;0x1200a9;;;BU)')\n Set-Acl -LiteralPath $target -AclObject $fileACL\n if($Hash -notmatch '^[0-9a-f]{64}$' -or (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -ine $Hash){throw 'agent hash'}\n $image=Join-Path $Mount 'ProgramData\\Bivouac\\Image'\n New-OfflineDirectory $Mount $image\n $private=[Security.AccessControl.DirectorySecurity]::new();$private.SetSecurityDescriptorSddlForm('O:BAD:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)')\n Set-Acl -LiteralPath (Split-Path -Parent $image) -AclObject $private\n Set-Acl -LiteralPath $image -AclObject $private\n}\n"
